// Renders the same content twice: rich HTML for the record, plain text for Telegram.
const jobs = $input.all().map((i) => i.json).filter((r) => r && r.id !== undefined);
const esc = (s) =>
  String(s === null || s === undefined ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const color = (s) => (s >= 85 ? '#0a7d32' : s >= 70 ? '#8a6d00' : '#666');

const rows = jobs
  .map(
    (j, i) =>
      '<tr>' +
      '<td style="padding:10px 8px;color:#888">' + (i + 1) + '</td>' +
      '<td style="padding:10px 8px"><a href="' + esc(j.url) + '" style="color:#111;font-weight:600;text-decoration:none">' + esc(j.title) + '</a>' +
      '<div style="color:#666;font-size:13px">' + esc(j.company) + ' &middot; ' + esc(j.location || '-') + ' &middot; ' + esc(j.source) + '</div></td>' +
      '<td style="padding:10px 8px;text-align:right;color:' + color(j.score) + ';font-weight:700">' + esc(j.score) + '</td>' +
      '</tr>'
  )
  .join('');

const html =
  '<div style="font-family:-apple-system,Segoe UI,sans-serif;max-width:640px">' +
  '<h2 style="margin:0 0 4px">JobPilot &middot; ' + new Date().toISOString().slice(0, 10) + '</h2>' +
  '<p style="color:#666;margin:0 0 16px">' + jobs.length + ' roles scored 70+ since the last digest.</p>' +
  (jobs.length ? '<table style="border-collapse:collapse;width:100%">' + rows + '</table>' : '<p>No new matches today.</p>') +
  '</div>';

const telegram =
  'JobPilot - ' + jobs.length + ' new match(es)\n\n' +
  (jobs.length
    ? jobs
        .map((j, i) => i + 1 + '. [' + j.score + '] ' + j.title + ' - ' + j.company + '\n' + (j.url || ''))
        .join('\n\n')
        .slice(0, 3400)
    : 'Nothing above the bar today. The pipeline is still running.');

const q = (v) => "'" + String(v).replace(/\u0000/g, '').replace(/'/g, "''") + "'";
const delivered = $env.TELEGRAM_CHAT_ID ? 'telegram' : 'stored-only';

return [
  {
    json: {
      count: jobs.length,
      html,
      telegram_text: telegram,
      delivered_via: delivered,
      save_sql:
        'INSERT INTO digests (job_count, html, delivered_via) VALUES (' +
        jobs.length +
        ',' +
        q(html) +
        ',' +
        q(delivered) +
        ');',
    },
  },
];

const d = $('Build digest').first().json;
const telegram = $env.TELEGRAM_CHAT_ID ? 'enabled' : 'skipped (no TELEGRAM_CHAT_ID)';
return [
  {
    json: {
      matches: d.count,
      telegram,
      html_bytes: d.html.length,
      note: d.count
        ? 'Digest rendered. Open the digests table to view the HTML.'
        : 'No job scored 70+ today. Lower the threshold in "Top matches" if this repeats.',
    },
  },
];
